import{_ as e,o as i,c as a,ah as r}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Extracurricular activities","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/activites-extrascolaires.md","filePath":"src/en/guide/admin/activites-extrascolaires.md"}'),s={name:"en/guide/admin/activites-extrascolaires.md"};function o(c,t,n,l,d,u){return i(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="extracurricular-activities" tabindex="-1">Extracurricular activities <a class="header-anchor" href="#extracurricular-activities" aria-label="Permalink to &quot;Extracurricular activities&quot;">​</a></h1><p>This section covers setting up the extracurricular activity catalog (swimming, drama, etc.) and scheduling its sessions. Tracking attendance at these sessions is then the student-life role&#39;s job, not administration&#39;s.</p><h2 id="create-an-activity" tabindex="-1">Create an activity <a class="header-anchor" href="#create-an-activity" aria-label="Permalink to &quot;Create an activity&quot;">​</a></h2><p><strong>Extracurricular Activities → Extracurricular Activities</strong> lists the instance&#39;s activity catalog.</p><p>To create an activity:</p><ol><li>Click <strong>New activity</strong>.</li><li>Fill in the <strong>Name</strong> and, optionally, a <strong>Description</strong>.</li><li>Click <strong>Save</strong>.</li></ol><h2 id="schedule-a-session" tabindex="-1">Schedule a session <a class="header-anchor" href="#schedule-a-session" aria-label="Permalink to &quot;Schedule a session&quot;">​</a></h2><p><strong>Extracurricular Activities → Extracurricular Sessions</strong> schedules recurring slots for an activity, by site and level, with a designated supervisor.</p><p>To create a session:</p><ol><li>Click <strong>New session</strong>.</li><li>Fill in the &quot;Activity&quot; section fields below.</li><li>Fill in the &quot;Schedule&quot; section fields below.</li><li>Click <strong>Save</strong>.</li></ol><p>&quot;Activity&quot; section:</p><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Activity</td><td>chosen from the catalog</td></tr><tr><td>Site</td><td>—</td></tr><tr><td>Department</td><td>the level this session is for</td></tr><tr><td>Supervisor</td><td>staff member responsible for the session</td></tr></tbody></table><p>&quot;Schedule&quot; section:</p><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Day of week</td><td>—</td></tr><tr><td>Start time</td><td>—</td></tr><tr><td>End time</td><td>—</td></tr></tbody></table><p>Each session can then be edited or deleted individually from the session list.</p>',15)])])}const v=e(s,[["render",o]]);export{p as __pageData,v as default};
